function cms_icon(string $name): string
{
    return CMS_ICONS[$name] ?? '';
}

/** Redes sociales configuradas (sólo las que tienen URL). */
function cms_social_links(): array
{
    $s = cms_settings()['social'] ?? [];
    $labels = ['linkedin' => 'LinkedIn', 'facebook' => 'Facebook', 'x' => 'X', 'instagram' => 'Instagram', 'behance' => 'Behance', 'youtube' => 'YouTube'];
    $out = [];
    foreach ($labels as $k => $label) {
        if (!empty($s[$k])) $out[] = ['key' => $k, 'label' => $label, 'url' => $s[$k]];
    }
    return $out;
}

function cms_social_html(string $cls = ''): string
{
    $out = '<div class="cms-social ' . $cls . '">';
    foreach (cms_social_links() as $l) {
        $out .= '<a href="' . cms_e($l['url']) . '" target="_blank" rel="noopener" aria-label="' . cms_e($l['label']) . '" title="' . cms_e($l['label']) . '">' . cms_icon($l['key']) . '</a>';
    }
    return $out . '</div>';
}
